// Records how each firmware release lays out its config on the wire, read from the
// firmware's own deserializer (confgenerator.c, generated by VESC Tool but compiled
// into the firmware). The config tests compare our definitions against this file,
// so a mismatch between the XML and the real firmware fails the build.
// Run with: npm run gen:fw-layouts   (needs network access to GitHub)

import { mkdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const outFile = join(here, '..', 'src', 'config', '__fixtures__', 'fw-layouts.json')

/** Firmware version → release branch in https://github.com/vedderb/bldc */
const RELEASES: Record<string, string> = {
  '6.02': 'release_6_02',
  '6.05': 'release_6_05',
  '6.06': 'release_6_06',
  '7.00': 'release_7_00',
}

/** [name, wire type] or [name, wire type, fixed-point scale] */
type Field = [string, string] | [string, string, number]

const PATTERNS: [RegExp, (m: RegExpMatchArray) => [string] | [string, number]][] = [
  [/^\(int8_t\)buffer\[ind\+\+\]$/, () => ['i8']],
  [/^buffer\[ind\+\+\]$/, () => ['u8']],
  [/^buffer_get_float16\(buffer, *([0-9.e+-]+), *&ind\)$/, (m) => ['f16', Number(m[1])]],
  [/^buffer_get_float32\(buffer, *([0-9.e+-]+), *&ind\)$/, (m) => ['f32', Number(m[1])]],
  [/^buffer_get_float32_auto\(buffer, *&ind\)$/, () => ['f32auto']],
  [/^buffer_get_(u?int(?:16|32))\(buffer, *&ind\)$/, (m) => [m[1].replace('uint', 'u').replace('int', 'i')]],
]

function parseBody(src: string, kind: string): Field[] {
  const start = src.indexOf(`bool confgenerator_deserialize_${kind}(`)
  if (start < 0) throw new Error(`No deserializer for ${kind}`)
  const end = src.indexOf('\n}', start)
  const fields: Field[] = []
  for (const line of src.slice(start, end).split('\n')) {
    const m = /^\s*conf->(\S+)\s*=\s*(.+);\s*$/.exec(line)
    if (!m) continue
    // conf->foc_hall_table[3] is VESC Tool's foc_hall_table__3
    const name = m[1].replace(/\[(\d+)\]/g, '__$1')
    const rhs = m[2].trim()
    const hit = PATTERNS.find(([re]) => re.test(rhs))
    if (!hit) throw new Error(`${kind}: don't know how to read "${rhs}" for ${name}`)
    fields.push([name, ...hit[1](rhs.match(hit[0])!)] as Field)
  }
  return fields
}

function signature(header: string, define: string): number {
  const m = new RegExp(`#define\\s+${define}\\s+(\\d+)`).exec(header)
  if (!m) throw new Error(`No ${define}`)
  return Number(m[1])
}

async function get(branch: string, file: string): Promise<string> {
  const url = `https://raw.githubusercontent.com/vedderb/bldc/${branch}/${file}`
  const res = await fetch(url)
  if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`)
  return res.text()
}

const out: Record<string, Record<string, { signature: number; fields: Field[] }>> = {}
for (const [fw, branch] of Object.entries(RELEASES)) {
  const [c, h] = await Promise.all([get(branch, 'confgenerator.c'), get(branch, 'confgenerator.h')])
  out[fw] = {
    mcconf: { signature: signature(h, 'MCCONF_SIGNATURE'), fields: parseBody(c, 'mcconf') },
    appconf: { signature: signature(h, 'APPCONF_SIGNATURE'), fields: parseBody(c, 'appconf') },
  }
  console.log(`${fw}: mcconf ${out[fw].mcconf.fields.length} fields, appconf ${out[fw].appconf.fields.length} fields`)
}

mkdirSync(dirname(outFile), { recursive: true })
// One field per line keeps diffs readable when a firmware version is added.
const body = JSON.stringify(out, null, 1).replace(/\[\s+("[^"]+"),\s+("[^"]+")(?:,\s+([0-9.e+-]+))?\s+\]/g, (_m, a, b, c) =>
  c ? `[${a}, ${b}, ${c}]` : `[${a}, ${b}]`,
)
writeFileSync(outFile, body + '\n')
console.log(`Wrote ${outFile}`)
